// Same rule as the catalog: active row in nc_apps and email in allowed_emails (empty = all)
const input = $("Check access").first().json;
const email = String(input.email ?? "").trim().toLowerCase();
const row = $input.first().json;
const deny = (message) => [{ json: { allowed: false, error: { code: "app_forbidden", message } } }];

if (!email) return deny("Session has no email.");
if (!row.app_id) return deny("This app is not registered on the server.");
if (row.enabled !== true) return deny("This app is disabled on the server.");
const allowed = String(row.allowed_emails ?? "").split(",").map((s) => s.trim().toLowerCase()).filter(Boolean);
if (allowed.length && !allowed.includes(email)) return deny("Your account does not have access to this app.");
return [{ json: { allowed: true } }];
